83	func cmdQuery(dataFile string, argv []string, stdout, stderr io.Writer) int {
84		fs := newFlagSet("query", stderr)
85		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
86		id := fs.String("id", "", "要查询的包裹编号")
87		if ok, code := parseFlags(fs, argv, stdout, stderr, printQueryHelp); !ok {
88			return code
89		}
90	
91		cleanIDVal, err := cleanID("包裹编号", *id)
92		if err != nil {
93			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
94			return exitBusiness
95		}
96	
97		store, err := Open(dataFile)
98		if err != nil {
99			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
100			return exitBusiness
101		}
102		p, err := store.Query(cleanIDVal)
103		if err != nil {
104			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
105			return exitBusiness
106		}
107	
108		fmt.Fprintf(stdout, "包裹编号: %s\n当前站点: %s\n当前状态: %s\n", p.ID, p.Station, p.Status)
109		if p.Status == statusDelivering {
110			for i := len(p.Trail) - 1; i >= 0; i-- {
111				if e := p.Trail[i]; e.Op == "出站" || e.Op == "续接" {
112					fmt.Fprintf(stdout, "当前批次: %s\n当前配送员: %s\n", e.Batch, e.Courier)
113					break
114				}
115			}
116		}
117		if f := store.ActiveFreeze(cleanIDVal); f != nil {
118			fmt.Fprintf(stdout, "当前未解除异常: 异常单号: %s    原因: %s    冻结时间: %s\n",
119				f.Incident, f.Reason, f.Time.Format(timeFmt))
120		}
121		fmt.Fprintf(stdout, "轨迹（按提交顺序，共 %d 条）:\n", len(p.Trail))
122		for i, e := range p.Trail {
123			switch e.Op {
124			case "退回":
125				fmt.Fprintf(stdout, "  %d. 操作: 退回    源站: %s    目的站: %s    退回请求号: %s    原交接请求号: %s    原因: %s    时间: %s\n",
126					i+1, e.From, e.Station, e.Request, e.RefRequest, e.Reason, e.Time.Format(timeFmt))
127			case "出站":
128				fmt.Fprintf(stdout, "  %d. 操作: 出站    站点: %s    批次号: %s    配送员: %s    时间: %s\n",
129					i+1, e.Station, e.Batch, e.Courier, e.Time.Format(timeFmt))
130			case "回执":
131				if e.Result == resultFailed {
132					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    原因: %s    请求号: %s    时间: %s\n",
133						i+1, e.Station, e.Batch, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
134				} else {
135					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    请求号: %s    时间: %s\n",
136						i+1, e.Station, e.Batch, e.Result, e.Request, e.Time.Format(timeFmt))
137				}
138			case "冻结":
139				fmt.Fprintf(stdout, "  %d. 操作: 冻结    站点: %s    异常单号: %s    原因: %s    时间: %s\n",
140					i+1, e.Station, e.Incident, e.Reason, e.Time.Format(timeFmt))
141			case "解除冻结":
142				fmt.Fprintf(stdout, "  %d. 操作: 解除冻结    站点: %s    异常单号: %s    解除请求号: %s    处理说明: %s    时间: %s\n",
143					i+1, e.Station, e.Incident, e.Request, e.Note, e.Time.Format(timeFmt))
144			case "收回":
145				fmt.Fprintf(stdout, "  %d. 操作: 收回    站点: %s    批次号: %s    中止请求号: %s    原因: %s    时间: %s\n",
146					i+1, e.Station, e.Batch, e.Request, e.Reason, e.Time.Format(timeFmt))
147			case "续接":
148				fmt.Fprintf(stdout, "  %d. 操作: 续接    站点: %s    原批次号: %s    新批次号: %s    新配送员: %s    续接请求号: %s    原因: %s    时间: %s\n",
149					i+1, e.Station, e.FromBatch, e.Batch, e.Courier, e.Request, e.Reason, e.Time.Format(timeFmt))
150			default:
151				req := e.Request
152				if req == "" {
153					req = "-"
154				}
155				fmt.Fprintf(stdout, "  %d. 操作: %s    站点: %s    请求号: %s    时间: %s\n",
156					i+1, e.Op, e.Station, req, e.Time.Format(timeFmt))
157			}
158		}
159		return exitOK
160	}
