162	func cmdHandoff(dataFile string, argv []string, stdout, stderr io.Writer) int {
163		fs := newFlagSet("handoff", stderr)
164		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
165		request := fs.String("request", "", "交接请求号（用于去重）")
166		from := fs.String("from", "", "源站点")
167		to := fs.String("to", "", "目的站点")
168		var parcels stringList
169		fs.Var(&parcels, "parcel", "包裹编号，可重复指定；集合不可为空或含重复编号")
170		if ok, code := parseFlags(fs, argv, stdout, stderr, printHandoffHelp); !ok {
171			return code
172		}
173	
174		cleanReq, err := cleanID("请求号", *request)
175		if err != nil {
176			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
177			return exitBusiness
178		}
179		cleanFrom, err := cleanID("源站点", *from)
180		if err != nil {
181			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
182			return exitBusiness
183		}
184		cleanTo, err := cleanID("目的站点", *to)
185		if err != nil {
186			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
187			return exitBusiness
188		}
189		if len(parcels) == 0 {
190			fmt.Fprintf(stderr, "%s handoff: 包裹集合不可为空，至少需要一个 --parcel\n", appName)
191			return exitBusiness
192		}
193		cleanParcels := make([]string, 0, len(parcels))
194		seen := make(map[string]bool, len(parcels))
195		for _, raw := range parcels {
196			id, err := cleanID("包裹编号", raw)
197			if err != nil {
198				fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
199				return exitBusiness
200			}
201			if seen[id] {
202				fmt.Fprintf(stderr, "%s handoff: 包裹集合中编号 %q 重复\n", appName, id)
203				return exitBusiness
204			}
205			seen[id] = true
206			cleanParcels = append(cleanParcels, id)
207		}
208		if cleanFrom == cleanTo {
209			fmt.Fprintf(stderr, "%s handoff: 源站点与目的站点不能相同（均为 %q）\n", appName, cleanFrom)
210			return exitBusiness
211		}
212	
213		store, err := Open(dataFile)
214		if err != nil {
215			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
216			return exitBusiness
217		}
218		result, replayed, err := store.Handoff(cleanReq, cleanFrom, cleanTo, cleanParcels, now())
219		if err != nil {
220			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
221			return exitBusiness
222		}
223	
224		headline := "交接成功"
225		if replayed {
226			headline = "交接成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
227		}
228		fmt.Fprintf(stdout, "%s\n请求号: %s\n源站点: %s\n目的站点: %s\n包裹（%d 件）:\n",
229			headline, result.Request, result.From, result.To, len(result.Parcels))
230		for _, id := range result.Parcels {
231			fmt.Fprintf(stdout, "  - %s\n", id)
232		}
233		fmt.Fprintf(stdout, "发生时间: %s\n", result.Time.Format(timeFmt))
234		return exitOK
235	}
