436	// receiptFileRecord 是回执整批导入文件中的单条记录（JSON）。
437	type receiptFileRecord struct {
438		Request string `json:"request"`
439		Batch   string `json:"batch"`
440		Parcel  string `json:"parcel"`
441		Result  string `json:"result"`
442		Reason  string `json:"reason"`
443	}
444	
445	// loadReceiptImportFile 读取并解析回执整批导入文件。文件为有序且非空的
446	// JSON 数组，元素为 request/batch/parcel/result/reason 字段的对象；
447	// 文件只读，绝不改写。任一记录清洗后不合法或请求号在文件内重复，
448	// 都返回带记录位置的错误，整份不予导入。
449	func loadReceiptImportFile(path string) ([]ReceiptImportRecord, error) {
450		raw, err := os.ReadFile(path)
451		if err != nil {
452			return nil, fmt.Errorf("读取回执导入文件失败: %w", err)
453		}
454		dec := json.NewDecoder(bytes.NewReader(raw))
455		dec.DisallowUnknownFields()
456		var records []receiptFileRecord
457		if err := dec.Decode(&records); err != nil {
458			return nil, fmt.Errorf("解析回执导入文件失败: %w", err)
459		}
460		var extra any
461		if err := dec.Decode(&extra); err != io.EOF {
462			return nil, fmt.Errorf("解析回执导入文件失败: 回执列表之后存在多余内容")
463		}
464		if len(records) == 0 {
465			return nil, fmt.Errorf("回执导入文件必须是有序且非空的回执列表")
466		}
467	
468		clean := make([]ReceiptImportRecord, 0, len(records))
469		seen := make(map[string]bool, len(records))
470		for i, rawRec := range records {
471			rec, err := cleanReceiptImportRecord(rawRec)
472			if err != nil {
473				return nil, fmt.Errorf("第 %d 条记录: %w", i+1, err)
474			}
475			if seen[rec.Request] {
476				return nil, fmt.Errorf("第 %d 条记录: 回执请求号 %q 在文件内重复", i+1, rec.Request)
477			}
478			seen[rec.Request] = true
479			clean = append(clean, rec)
480		}
481		return clean, nil
482	}
483	
484	// cleanReceiptImportRecord 清洗并校验一条导入记录：各标识去除两端空白后不可为空；
485	// 结果为失败时必须给出清理后非空的原因，签收时不可带原因。
486	func cleanReceiptImportRecord(raw receiptFileRecord) (ReceiptImportRecord, error) {
487		var rec ReceiptImportRecord
488		var err error
489		if rec.Request, err = cleanID("回执请求号", raw.Request); err != nil {
490			return rec, err
491		}
492		if rec.Batch, err = cleanID("批次号", raw.Batch); err != nil {
493			return rec, err
494		}
495		if rec.Parcel, err = cleanID("包裹编号", raw.Parcel); err != nil {
496			return rec, err
497		}
498		if rec.Result, err = cleanID("回执结果", raw.Result); err != nil {
499			return rec, err
500		}
501		if rec.Result != resultSigned && rec.Result != resultFailed {
502			return rec, fmt.Errorf("回执结果只能是 %q 或 %q，得到 %q", resultSigned, resultFailed, rec.Result)
503		}
504		rec.Reason = strings.TrimSpace(raw.Reason)
505		if rec.Result == resultFailed && rec.Reason == "" {
506			return rec, fmt.Errorf("结果为失败时原因不可为空或仅含空白")
507		}
508		if rec.Result == resultSigned && rec.Reason != "" {
509			return rec, fmt.Errorf("结果为签收时不可带原因")
510		}
511		return rec, nil
512	}
