581		store, err := Open(dataFile)
582		if err != nil {
583			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
584			return exitBusiness
585		}
586		b, err := store.BatchQuery(cleanIDVal)
587		if err != nil {
588			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
589			return exitBusiness
590		}
591	
592		status := "配送中"
593		if b.Done() {
594			status = "已完成"
595		}
596		ab := store.BatchAbort(cleanIDVal)
597		if ab != nil {
598			status = "已中止"
599		}
600		tr := store.BatchTransferSource(cleanIDVal)
601		if tr != nil {
602			status = "已转交"
603		}
604		timeLabel := "出站时间"
605		if b.RelayedFrom != "" {
606			timeLabel = "接手时间"
607		}
608		fmt.Fprintf(stdout, "批次号: %s\n出发站: %s\n配送员: %s\n%s: %s\n批次状态: %s\n",
609			b.Batch, b.Station, b.Courier, timeLabel, b.Time.Format(timeFmt), status)
610		if b.RelayedFrom != "" {
611			src := store.TransferOf(b.RelayRequest)
612			fmt.Fprintf(stdout, "批次来源: 续接自批次 %s（原配送员: %s，续接请求号: %s）\n",
613				b.RelayedFrom, src.FromCourier, b.RelayRequest)
614		}
615		if ab != nil {
616			fmt.Fprintf(stdout, "中止请求号: %s\n中止原因: %s\n中止时间: %s\n",
617				ab.Request, ab.Reason, ab.Time.Format(timeFmt))
618		}
619		if tr != nil {
620			fmt.Fprintf(stdout, "转交去向: 批次 %s（新配送员: %s）\n续接请求号: %s\n续接原因: %s\n转交时间: %s\n",
621				tr.ToBatch, tr.ToCourier, tr.Request, tr.Reason, tr.Time.Format(timeFmt))
622		}
623		fmt.Fprintf(stdout, "逐件回执（%d/%d 已回执）:\n", len(b.Receipts), len(b.Parcels))
624		for _, pid := range b.Parcels {
625			e, ok := b.Receipts[pid]
626			if !ok {
627				switch {
628				case tr != nil:
629					fmt.Fprintf(stdout, "  - %s    已转交    去向批次: %s    续接请求号: %s    时间: %s\n",
630						pid, tr.ToBatch, tr.Request, tr.Time.Format(timeFmt))
631				case ab != nil:
632					fmt.Fprintf(stdout, "  - %s    已收回    中止请求号: %s    原因: %s    时间: %s\n",
633						pid, ab.Request, ab.Reason, ab.Time.Format(timeFmt))
634				default:
635					fmt.Fprintf(stdout, "  - %s    未回执\n", pid)
636				}
637				continue
638			}
639			if e.Result == resultFailed {
640				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    原因: %s    请求号: %s    时间: %s\n",
641					pid, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
642			} else {
643				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    请求号: %s    时间: %s\n",
644					pid, e.Result, e.Request, e.Time.Format(timeFmt))
645			}
646		}
647		return exitOK
648	}
