	if err != nil {
		fmt.Fprintf(stderr, "%s unfreeze: %v\n", appName, err)
		return exitBusiness
	}

	store, err := Open(dataFile)
	if err != nil {
		fmt.Fprintf(stderr, "%s unfreeze: %v\n", appName, err)
		return exitBusiness
	}
