695	// ActiveFreeze 返回一件包裹当前未解除异常单的冻结结果；包裹不存在或当前未冻结时返回 nil。
696	func (s *Store) ActiveFreeze(id string) *FreezeResult {
697		p, ok := s.data.Parcels[id]
698		if !ok {
699			return nil
700		}
701		if no := activeFreeze(p); no != "" {
702			return s.data.Freezes[no]
703		}
704		return nil
705	}
