954	// Receipt 提交一件包裹在某个配送批次下的回执。
955	//
956	// 首次回执：批次必须存在，包裹必须属于该批次、尚未在该批次回执，且当前仍在该批次
957	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
958	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
959	// 原因（失败时）、请求号和时间的回执记录；全部成员回执后批次自动完成。
960	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
961	// true，不重新检查当前状态，即使失败包裹已进入新批次；请求号相同但内容不同报冲突。
962	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
963	// 失败的首次回执不占用请求号。
964	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
965		res, replayed, undo, err := s.applyReceipt(request, batch, parcel, result, reason, now)
966		if err != nil || replayed {
967			return res, replayed, err
968		}
969		if err := s.save(); err != nil {
970			undo() // 落盘失败：回滚内存变更，保留原有有效数据
971			return nil, false, err
972		}
973		return res, false, nil
974	}
