976	// applyReceipt 在内存台账上校验并应用一条回执（不落盘），是 Receipt 与
977	// ImportReceipts 共用的核心。全部校验通过后才会改动数据；返回的 undo 可在
978	// 整体保存失败时撤销本次改动（重放或校验失败时 undo 为 nil）。
979	func (s *Store) applyReceipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, undo func(), err error) {
980		if saved, ok := s.data.Receipts[request]; ok {
981			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
982				return saved, true, nil, nil
983			}
984			return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
985				request, saved.Batch, saved.Parcel, saved.Result)
986		}
987	
988		b, ok := s.data.Batches[batch]
989		if !ok {
990			return nil, false, nil, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
991		}
992		member := false
993		for _, id := range b.Parcels {
994			if id == parcel {
995				member = true
996				break
997			}
998		}
999		if !member {
1000			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
1001		}
1002		if _, done := b.Receipts[parcel]; done {
1003			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能成功回执一次", parcel, batch)
1004		}
1005		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
1006		if p.Status != statusDelivering || currentBatch(p) != batch {
1007			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
1008		}
1009	
1010		res = &ReceiptResult{
1011			Request: request,
1012			Batch:   batch,
1013			Parcel:  parcel,
1014			Result:  result,
1015			Reason:  reason,
1016			Time:    now,
1017		}
1018		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
1019	
1020		// 记录旧值，undo 在整体落盘失败时回滚。
1021		oldStatus, oldStation := p.Status, p.Station
1022		oldTrailLen := len(p.Trail)
1023	
1024		if result == resultSigned {
1025			p.Status = statusSigned // 站点保留不变
1026		} else {
1027			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
1028			p.Station = b.Station
1029		}
1030		p.Trail = append(p.Trail, Event{
1031			Op:      "回执",
1032			Station: p.Station,
1033			Batch:   batch,
1034			Result:  result,
1035			Reason:  reason,
1036			Request: request,
1037			Time:    now,
1038		})
1039		b.Receipts[parcel] = entry
1040		s.data.Receipts[request] = res
1041	
1042		undo = func() {
1043			delete(s.data.Receipts, request)
1044			delete(b.Receipts, parcel)
1045			p.Status, p.Station = oldStatus, oldStation
1046			p.Trail = p.Trail[:oldTrailLen]
1047		}
1048		return res, false, undo, nil
1049	}
