1108	// fork 返回当前台账的深拷贝副本，供整批导入试算；副本上的任何改动都不影响原台账。
1109	func (s *Store) fork() (*Store, error) {
1110		buf, err := json.Marshal(s.data)
1111		if err != nil {
1112			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1113		}
1114		var cp ledgerFile
1115		if err := json.Unmarshal(buf, &cp); err != nil {
1116			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1117		}
1118		return &Store{path: s.path, data: cp}, nil
1119	}
