1180	// Unfreeze 解除一件包裹当前的异常冻结。
1181	//
1182	// 首次解除：异常单必须存在且尚未解除，并且仍是该包裹当前冻结对应的异常单；
1183	// 异常单不存在、已解除或对应关系不符均拒绝。成功后包裹在原站恢复在站，原异常单
1184	// 永久标记为已解除（异常单号不得复用），追加一条含异常单号、解除请求号、处理说明及
1185	// 时间的解除记录，原冻结记录不删改；之后可用新异常单再次冻结。
1186	// 解除只是管理记录，不移动实物、不算新流转。
1187	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
1188	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
1189	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
1190	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
1191		if saved, ok := s.data.Unfreezes[request]; ok {
1192			if saved.Incident == incident && saved.Note == note {
1193				return saved, true, nil
1194			}
1195			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
1196				request, saved.Incident, saved.Note)
1197		}
1198	
1199		f, ok := s.data.Freezes[incident]
1200		if !ok {
1201			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
1202		}
1203		if f.ReleasedBy != "" {
1204			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
1205		}
1206		p, ok := s.data.Parcels[f.Parcel]
1207		if !ok {
1208			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
1209		}
1210		if p.Status != statusFrozen || activeFreeze(p) != incident {
1211			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
1212				incident, f.Parcel, activeFreeze(p))
1213		}
1214	
1215		res = &UnfreezeResult{
1216			Request:  request,
1217			Incident: incident,
1218			Parcel:   f.Parcel,
1219			Note:     note,
1220			Time:     now,
1221		}
1222		s.data.Unfreezes[request] = res
1223		f.ReleasedBy = request
1224	
1225		// 记录旧值，落盘失败时整体回滚。
1226		oldStatus := p.Status
1227		oldTrail := append([]Event(nil), p.Trail...)
1228		p.Status = statusInStation // 在原站恢复在站，站点不变
1229		p.Trail = append(p.Trail, Event{
1230			Op:       "解除冻结",
1231			Station:  f.Station,
1232			Incident: incident,
1233			Request:  request,
1234			Note:     note,
1235			Time:     now,
1236		})
1237	
1238		if err := s.save(); err != nil {
1239			delete(s.data.Unfreezes, request)
1240			f.ReleasedBy = ""
1241			p.Status, p.Trail = oldStatus, oldTrail
1242			return nil, false, err
1243		}
1244		return res, false, nil
1245	}
