1247	// Abort 中止一个配送批次：配送员已将该批次全部尚未回执的包裹实物收回出发站。
1248	// 成员与站点取自原批次结果，不允许另选成员或站点。
1249	//
1250	// 首次中止：批次必须存在、尚未完成且未中止，且至少有一件未回执成员；这些成员
1251	// 必须仍在原批次配送中、归属出发站，任一不符整批拒绝、不作任何改动。已回执成员
1252	// 及其回执完全保留，即使它们已进入其他批次或被冻结也不阻止中止，不检查也不改变
1253	// 其当前状态。全部满足时按原成员顺序将全部未回执件恢复“在站”（站点为出发站），
1254	// 各追加一条含批次、中止请求号、原因、站点和时间的收回记录；收回不是失败回执，
1255	// 批次回执记录不变。中止永久关闭原批次，原成员顺序、配送员与出站时间保留不变。
1256	// 收回算新的流转，收回后不能退回出站前的旧交接；收回件可交接、冻结或再次出站，
1257	// 但不能首次回执旧批次（receipt 与 receipt-import 同样遵守）。
1258	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且批次、
1259	// 清理后的原因相同，直接返回首次收回集合与时间，replayed 为 true，不重新计算成员、
1260	// 不检查当前状态、不改写台账；请求号相同但批次或原因不同报冲突。
1261	// 每批只能成功中止一次：换请求号再中止或中止已正常完成的批次均拒绝；
1262	// 失败的首次中止不占用请求号。
1263	func (s *Store) Abort(request, batch, reason string, now time.Time) (res *AbortResult, replayed bool, err error) {
1264		if saved, ok := s.data.Aborts[request]; ok {
1265			if saved.Batch == batch && saved.Reason == reason {
1266				return saved, true, nil
1267			}
1268			return nil, false, fmt.Errorf("中止请求号 %q 已用于一次不同的中止（批次=%q 原因=%q），内容冲突",
1269				request, saved.Batch, saved.Reason)
1270		}
1271	
1272		b, ok := s.data.Batches[batch]
1273		if !ok {
1274			return nil, false, fmt.Errorf("中止失败：批次号 %q 不存在", batch)
1275		}
1276		if b.AbortedBy != "" {
1277			return nil, false, fmt.Errorf("中止失败：批次 %q 已中止（中止请求号 %q），每批只能成功中止一次", batch, b.AbortedBy)
1278		}
1279		if b.TransferredBy != "" {
1280			return nil, false, fmt.Errorf("中止失败：批次 %q 已转交（续接请求号 %q），不能中止", batch, b.TransferredBy)
1281		}
1282		if b.Done() {
1283			return nil, false, fmt.Errorf("中止失败：批次 %q 已全部回执完成，不能中止", batch)
1284		}
1285	
1286		// 按原成员顺序挑出全部未回执成员（批次未完成，必至少有一件）。
1287		recalled := make([]string, 0, len(b.Parcels)-len(b.Receipts))
1288		for _, pid := range b.Parcels {
1289			if _, done := b.Receipts[pid]; !done {
1290				recalled = append(recalled, pid)
1291			}
1292		}
1293		if len(recalled) == 0 {
1294			return nil, false, fmt.Errorf("中止失败：批次 %q 没有未回执成员，不能中止", batch)
1295		}
1296	
1297		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
1298		for _, pid := range recalled {
1299			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
1300			if p.Status != statusDelivering || currentBatch(p) != batch || p.Station != b.Station {
1301				return nil, false, fmt.Errorf("中止失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批中止未执行",
1302					pid, p.Station, p.Status, batch, b.Station)
1303			}
1304		}
1305	
1306		res = &AbortResult{
1307			Request: request,
1308			Batch:   batch,
1309			Station: b.Station,
1310			Reason:  reason,
1311			Parcels: recalled,
1312			Time:    now,
1313		}
1314		s.data.Aborts[request] = res
1315		b.AbortedBy = request
1316	
1317		// 记录旧值，落盘失败时整体回滚。
1318		prev := make(map[string]struct {
1319			status string
1320			trail  []Event
1321		}, len(recalled))
1322		for _, pid := range recalled {
1323			p := s.data.Parcels[pid]
1324			prev[pid] = struct {
1325				status string
1326				trail  []Event
1327			}{p.Status, append([]Event(nil), p.Trail...)}
1328			p.Status = statusInStation // 实物已收回出发站，站点仍记出发站
1329			p.Trail = append(p.Trail, Event{
1330				Op:      "收回",
1331				Station: b.Station,
1332				Batch:   batch,
1333				Request: request,
1334				Reason:  reason,
1335				Time:    now,
1336			})
1337		}
1338	
1339		if err := s.save(); err != nil {
1340			delete(s.data.Aborts, request)
1341			b.AbortedBy = ""
1342			for pid, old := range prev {
1343				p := s.data.Parcels[pid]
1344				p.Status = old.status
1345				p.Trail = old.trail
1346			}
1347			return nil, false, err
1348		}
1349		return res, false, nil
1350	}
1351	
1352	// BatchAbort 返回一个配送批次的中止结果；批次不存在或未中止时返回 nil。
1353	func (s *Store) BatchAbort(batch string) *AbortResult {
1354		b, ok := s.data.Batches[batch]
1355		if !ok || b.AbortedBy == "" {
1356			return nil
1357		}
1358		return s.data.Aborts[b.AbortedBy]
1359	}
1360	
1361	// Transfer 把原批次全部尚未回执的包裹在配送途中整批交给另一配送员：
1362	// 新建批次继续配送，无需回站。成员与站点取自原批次，不允许另选成员或站点。
1363	//
1364	// 首次续接：原批次必须存在、仍开放（未中止、未转交）且有未回执成员；新批次号
1365	// 必须从未被出站或续接使用；新配送员必须与原配送员不同。未回执成员必须全部仍在
1366	// 原批次配送中且归属出发站，任一不符整批拒绝、不作任何改动。已回执成员不检查也
1367	// 不变更，其后续流转或冻结不阻止续接。全部满足时新批次按原成员顺序接纳全部未
1368	// 回执件，沿用出发站，记录新配送员及接手时间；包裹保持“配送中”及原站点，当前
1369	// 配送归属切换到新批次，各追加一条含请求号、前后批次、新配送员、站点、原因和
1370	// 时间的续接记录。原批次永久关闭为“已转交”，原成员、配送员、出站时间与真实
1371	// 回执保留不变；转交不算回执、收回或再次出站。续接算新的流转，续接后不能退回
1372	// 配送前的旧交接。
1373	// 续接请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且原批次、
1374	// 新批次、新配送员、清理后的原因相同，直接返回首次转交集合、续接信息及时间，
1375	// replayed 为 true，不检查现状、不重算成员、不改写台账；请求号相同但内容不同报
1376	// 冲突；失败的首次续接不占用请求号。
1377	func (s *Store) Transfer(request, fromBatch, toBatch, courier, reason string, now time.Time) (res *TransferResult, replayed bool, err error) {
1378		if saved, ok := s.data.Transfers[request]; ok {
1379			if saved.FromBatch == fromBatch && saved.ToBatch == toBatch && saved.ToCourier == courier && saved.Reason == reason {
1380				return saved, true, nil
1381			}
1382			return nil, false, fmt.Errorf("续接请求号 %q 已用于一次不同的续接（原批次=%q 新批次=%q 新配送员=%q），内容冲突",
1383				request, saved.FromBatch, saved.ToBatch, saved.ToCourier)
1384		}
1385	
1386		b, ok := s.data.Batches[fromBatch]
1387		if !ok {
1388			return nil, false, fmt.Errorf("续接失败：原批次号 %q 不存在", fromBatch)
1389		}
1390		if b.AbortedBy != "" {
1391			return nil, false, fmt.Errorf("续接失败：批次 %q 已中止（中止请求号 %q），不能续接", fromBatch, b.AbortedBy)
1392		}
1393		if b.TransferredBy != "" {
1394			return nil, false, fmt.Errorf("续接失败：批次 %q 已转交（续接请求号 %q），不能再次续接", fromBatch, b.TransferredBy)
1395		}
1396		if _, used := s.data.Batches[toBatch]; used {
1397			return nil, false, fmt.Errorf("续接失败：新批次号 %q 已被出站或续接使用，不能复用", toBatch)
1398		}
1399		if courier == b.Courier {
1400			return nil, false, fmt.Errorf("续接失败：新配送员 %q 不能与原批次 %q 的配送员相同", courier, fromBatch)
1401		}
1402	
1403		// 按原成员顺序挑出全部未回执成员（批次仍开放，必至少有一件）。
1404		moved := make([]string, 0, len(b.Parcels)-len(b.Receipts))
1405		for _, pid := range b.Parcels {
1406			if _, done := b.Receipts[pid]; !done {
1407				moved = append(moved, pid)
1408			}
1409		}
1410		if len(moved) == 0 {
1411			return nil, false, fmt.Errorf("续接失败：批次 %q 没有未回执成员，不能续接", fromBatch)
1412		}
1413	
1414		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
1415		for _, pid := range moved {
1416			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
1417			if p.Status != statusDelivering || currentBatch(p) != fromBatch || p.Station != b.Station {
1418				return nil, false, fmt.Errorf("续接失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批续接未执行",
1419					pid, p.Station, p.Status, fromBatch, b.Station)
1420			}
1421		}
1422	
1423		res = &TransferResult{
1424			Request:     request,
1425			FromBatch:   fromBatch,
1426			ToBatch:     toBatch,
1427			Station:     b.Station,
1428			FromCourier: b.Courier,
1429			ToCourier:   courier,
1430			Reason:      reason,
1431			Parcels:     append([]string(nil), moved...),
1432			Time:        now,
1433		}
1434		s.data.Transfers[request] = res
1435		s.data.Batches[toBatch] = &BatchResult{
1436			Batch:        toBatch,
1437			Station:      b.Station,
1438			Courier:      courier,
1439			Parcels:      append([]string(nil), moved...),
1440			Time:         now,
1441			Receipts:     map[string]*ReceiptEntry{},
1442			RelayedFrom:  fromBatch,
1443			RelayRequest: request,
1444		}
1445		b.TransferredBy = request
1446	
1447		// 记录旧值，落盘失败时整体回滚。包裹保持“配送中”及原站点，只追加续接轨迹。
1448		prev := make(map[string][]Event, len(moved))
1449		for _, pid := range moved {
1450			p := s.data.Parcels[pid]
1451			prev[pid] = append([]Event(nil), p.Trail...)
1452			p.Trail = append(p.Trail, Event{
1453				Op:        "续接",
1454				Station:   b.Station,
1455				Batch:     toBatch,
1456				FromBatch: fromBatch,
1457				Courier:   courier,
1458				Request:   request,
1459				Reason:    reason,
1460				Time:      now,
1461			})
1462		}
1463	
1464		if err := s.save(); err != nil {
1465			delete(s.data.Transfers, request)
1466			delete(s.data.Batches, toBatch)
1467			b.TransferredBy = ""
1468			for pid, old := range prev {
1469				s.data.Parcels[pid].Trail = old
1470			}
1471			return nil, false, err
1472		}
1473		return res, false, nil
1474	}
1475	
1476	// BatchTransferSource 返回以该批次为原批次的续接结果；批次不存在或未转交时返回 nil。
1477	func (s *Store) BatchTransferSource(batch string) *TransferResult {
1478		b, ok := s.data.Batches[batch]
1479		if !ok || b.TransferredBy == "" {
1480			return nil
1481		}
1482		return s.data.Transfers[b.TransferredBy]
1483	}
1484	
1485	// TransferOf 按续接请求号返回续接结果；不存在时返回 nil。
1486	func (s *Store) TransferOf(request string) *TransferResult {
1487		return s.data.Transfers[request]
1488	}
1489	
1490	// currentBatch 返回包裹当前配送归属的批次号（最后一条出站或续接记录的批次）；
1491	// 不在配送中返回空。续接不新增出站记录，但会把当前配送归属切换到新批次。
1492	func currentBatch(p *Parcel) string {
1493		for i := len(p.Trail) - 1; i >= 0; i-- {
1494			if p.Trail[i].Op == "出站" || p.Trail[i].Op == "续接" {
1495				return p.Trail[i].Batch
1496			}
1497		}
1498		return ""
1499	}
1500	
1501	// activeFreeze 返回包裹当前未解除冻结对应的异常单号；未冻结返回空。
1502	// 冻结状态与轨迹成对追加，故当前状态为异常冻结时最后一条冻结记录即为当前异常单。
1503	func activeFreeze(p *Parcel) string {
1504		if p.Status != statusFrozen {
1505			return ""
1506		}
1507		for i := len(p.Trail) - 1; i >= 0; i-- {
1508			if p.Trail[i].Op == "冻结" {
1509				return p.Trail[i].Incident
1510			}
1511		}
1512		return ""
1513	}
1514	
1515	// lastFlowEvent 返回轨迹中最后一条真实流转记录（交接/退回/出站/回执/收回）。
1516	// 冻结与解除只是管理记录，不算新流转，判定旧交接可否退回时须跳过它们。
1517	func lastFlowEvent(trail []Event) Event {
1518		for i := len(trail) - 1; i >= 0; i-- {
1519			switch trail[i].Op {
1520			case "冻结", "解除冻结":
1521				continue
1522			default:
1523				return trail[i]
1524			}
1525		}
1526		return Event{}
1527	}
1528	
1529	// BatchQuery 返回一个配送批次的出站结果与逐件回执进度；批次不存在时报错。
1530	func (s *Store) BatchQuery(batch string) (*BatchResult, error) {
1531		b, ok := s.data.Batches[batch]
1532		if !ok {
1533			return nil, fmt.Errorf("批次 %q 不存在", batch)
1534		}
1535		return b, nil
1536	}
1537	
1538	// sameOrder 判断两个列表长度与逐元素顺序完全一致。
1539	func sameOrder(a, b []string) bool {
1540		if len(a) != len(b) {
1541			return false
1542		}
1543		for i := range a {
1544			if a[i] != b[i] {
1545				return false
1546			}
1547		}
1548		return true
1549	}
1550	
1551	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
1552	func sameSet(a, b []string) bool {
1553		if len(a) != len(b) {
1554			return false
1555		}
1556		x := append([]string(nil), a...)
1557		y := append([]string(nil), b...)
1558		sort.Strings(x)
1559		sort.Strings(y)
1560		for i := range x {
1561			if x[i] != y[i] {
1562				return false
1563			}
1564		}
1565		return true
1566	}
1567	
1568	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
1569	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
1570	func (s *Store) save() error {
1571		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
1572			return fmt.Errorf("保存数据文件失败: %w", err)
1573		}
1574		buf, err := json.MarshalIndent(s.data, "", "  ")
1575		if err != nil {
1576			return fmt.Errorf("保存数据文件失败: %w", err)
1577		}
1578		buf = append(buf, '\n')
1579	
1580		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
1581		if err != nil {
1582			return fmt.Errorf("保存数据文件失败: %w", err)
1583		}
1584		tmpName := tmp.Name()
1585		cleanup := func() { _ = os.Remove(tmpName) }
1586	
1587		if _, err := tmp.Write(buf); err != nil {
1588			_ = tmp.Close()
1589			cleanup()
1590			return fmt.Errorf("保存数据文件失败: %w", err)
1591		}
1592		if err := tmp.Sync(); err != nil {
1593			_ = tmp.Close()
1594			cleanup()
1595			return fmt.Errorf("保存数据文件失败: %w", err)
1596		}
1597		if err := tmp.Close(); err != nil {
1598			cleanup()
1599			return fmt.Errorf("保存数据文件失败: %w", err)
1600		}
1601	
1602		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
1603		var check ledgerFile
1604		if err := json.Unmarshal(buf, &check); err != nil {
1605			cleanup()
1606			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
1607		}
1608	
1609		if err := os.Rename(tmpName, s.path); err != nil {
1610			cleanup()
1611			return fmt.Errorf("保存数据文件失败: %w", err)
1612		}
1613		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1614			_ = dir.Sync()
1615			_ = dir.Close()
1616		}
1617		return nil
1618	}
1619

